<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
use Sentinel\Repositories\PermissionRepository;
final class OpenShiftOfferService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access,private readonly ReplacementSuggestionService $suggestions,private readonly PermissionRepository $permissions) {}
    public function list(bool $self=false):array {$rows=$this->db->fetchAll('SELECT o.* FROM open_shift_offers o WHERE o.company_id=:company'.($self?' AND EXISTS(SELECT 1 FROM open_shift_candidates c WHERE c.company_id=o.company_id AND c.offer_id=o.offer_id AND c.employee_id=:employee)':'').' ORDER BY o.offer_id DESC LIMIT 200',$self?['company'=>$this->company(),'employee'=>$this->employee()]:['company'=>$this->company()]);$out=[];foreach($rows as$r){if(!$this->access->allowed($r['site_id']))continue;$r['expired']=$r['deadline_at']<gmdate('Y-m-d H:i:s');$r['candidates']=$this->db->fetchAll('SELECT employee_id,state,accepted_at FROM open_shift_candidates WHERE company_id=:company AND offer_id=:offer'.($self?' AND employee_id=:employee':''),$self?['company'=>$this->company(),'offer'=>$r['offer_id'],'employee'=>$this->employee()]:['company'=>$this->company(),'offer'=>$r['offer_id']]);$out[]=$r;}return $out;}
    public function broadcast(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['shift_id','deadline_at']);$shift=$this->row('shift_assignments','shift_assignment_id',$input['shift_id']??null);$this->access->requireSite($shift['site_id']);$deadline=$this->at($input['deadline_at']??null);if($deadline<=gmdate('Y-m-d H:i:s')||$deadline>$shift['shift_end_at']||strtotime($deadline.' UTC')>time()+7*86400)throw HttpException::unprocessable('Choose a future response deadline within the shift and next seven days.');if($this->db->fetch("SELECT offer_id FROM open_shift_offers WHERE company_id=:company AND shift_id=:shift AND state='OPEN' AND deadline_at>:now",['company'=>$this->company(),'shift'=>$shift['shift_assignment_id'],'now'=>gmdate('Y-m-d H:i:s')]))throw HttpException::conflict('This shift already has an open offer.');$eligible=$this->suggestions->suggest((string)$shift['shift_assignment_id'])['eligible'];if(count($eligible)>50)throw HttpException::unprocessable('More than 50 eligible guards; narrow the roster first.');if(!$eligible)throw HttpException::unprocessable('No eligible replacements are currently recorded.');$this->db->execute('INSERT INTO open_shift_offers(company_id,shift_id,site_id,expected_employee_id,deadline_at,created_by_user_id,created_at) VALUES(:company,:shift,:site,:employee,:deadline,:actor,:now)',['company'=>$this->company(),'shift'=>$shift['shift_assignment_id'],'site'=>$shift['site_id'],'employee'=>$shift['employee_id'],'deadline'=>$deadline,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);$result=$this->created('open_shift_offer');$sent=0;foreach($eligible as$e){$this->db->execute('INSERT INTO open_shift_candidates(company_id,offer_id,employee_id) VALUES(:company,:offer,:employee)',['company'=>$this->company(),'offer'=>$result['id'],'employee'=>$e['employee_id']]);foreach($this->db->fetchAll("SELECT user_id FROM users WHERE company_id=:company AND employee_id=:employee AND status='ACTIVE'",['company'=>$this->company(),'employee'=>$e['employee_id']])as$u){$user=(string)$u['user_id'];if(!$this->permissions->userHasPermission($user,'shift_offers.self'))continue;if($this->permissions->userHasPermission($user,'site_scope.restricted')&&!$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:user AND site_id=:site',['company'=>$this->company(),'user'=>$user,'site'=>$shift['site_id']]))continue;$this->db->execute('INSERT INTO notifications(company_id,recipient_user_id,event_type,title,message) VALUES(:company,:user,:type,:title,:message)',['company'=>$this->company(),'user'=>$user,'type'=>'OPEN_SHIFT_OFFER','title'=>'Open shift offer','message'=>'Offer #'.$result['id'].' for shift #'.$shift['shift_assignment_id'].' is available until '.$deadline.' UTC. Acceptance requires manager confirmation.']);$sent++;}}return $result+['notifications'=>$sent];});}
    public function accept(string $id):array {return $this->atomic(function()use($id){$offer=$this->row('open_shift_offers','offer_id',$id);$this->access->requireSite($offer['site_id']);if($offer['state']!=='OPEN'||$offer['deadline_at']<=gmdate('Y-m-d H:i:s'))throw HttpException::conflict('This offer has closed.');$employee=$this->employee();$candidate=$this->db->fetch('SELECT * FROM open_shift_candidates WHERE company_id=:company AND offer_id=:offer AND employee_id=:employee',['company'=>$this->company(),'offer'=>$id,'employee'=>$employee])??throw HttpException::notFound();if(!in_array($employee,array_column($this->suggestions->suggest((string)$offer['shift_id'])['eligible'],'employee_id'),true))throw HttpException::conflict('Your availability or eligibility changed.');if($candidate['state']==='ACCEPTED')return ['accepted'=>true,'assigned'=>false];if($candidate['state']!=='OFFERED')throw HttpException::conflict('Candidate state changed.');$this->db->execute("UPDATE open_shift_candidates SET state='ACCEPTED',accepted_by_user_id=:actor,accepted_at=:now WHERE company_id=:company AND candidate_id=:id",['actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s'),'company'=>$this->company(),'id'=>$candidate['candidate_id']]);$this->audit->record('open_shift_offer','candidate_accepted',$id);return ['accepted'=>true,'assigned'=>false,'note'=>'A manager must confirm the replacement.'];});}
    public function award(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision','employee_id','reason']);$offer=$this->row('open_shift_offers','offer_id',$id);$this->access->requireSite($offer['site_id']);if($offer['state']!=='OPEN'||$offer['deadline_at']<=gmdate('Y-m-d H:i:s')||$this->number($input['expected_revision']??null)!==(int)$offer['revision'])throw HttpException::conflict('Offer changed or expired.');$employee=(string)$this->number($input['employee_id']??null);if(!$this->db->fetch("SELECT candidate_id FROM open_shift_candidates WHERE company_id=:company AND offer_id=:offer AND employee_id=:employee AND state='ACCEPTED'",['company'=>$this->company(),'offer'=>$id,'employee'=>$employee]))throw HttpException::conflict('Choose a guard who accepted this offer.');$this->suggestions->approve((string)$offer['shift_id'],['expected_employee_id'=>$offer['expected_employee_id'],'replacement_employee_id'=>$employee,'reason'=>$this->text($input['reason']??null,500)]);$this->db->execute("UPDATE open_shift_offers SET state='AWARDED',revision=revision+1,awarded_employee_id=:employee WHERE company_id=:company AND offer_id=:id",['employee'=>$employee,'company'=>$this->company(),'id'=>$id]);$this->db->execute("UPDATE open_shift_candidates SET state=CASE WHEN employee_id=:employee THEN 'AWARDED' ELSE 'NOT_SELECTED' END WHERE company_id=:company AND offer_id=:offer",['employee'=>$employee,'company'=>$this->company(),'offer'=>$id]);$this->audit->record('open_shift_offer','manager_awarded',$id);return ['assigned'=>true];});}
    public function cancel(string $id):array {return $this->atomic(function()use($id){$r=$this->row('open_shift_offers','offer_id',$id);$this->access->requireSite($r['site_id']);if($r['state']!=='OPEN')throw HttpException::conflict('Offer is no longer open.');$this->db->execute("UPDATE open_shift_offers SET state='CANCELLED',revision=revision+1 WHERE company_id=:company AND offer_id=:id",['company'=>$this->company(),'id'=>$id]);$this->audit->record('open_shift_offer','cancelled',$id);return ['cancelled'=>true];});}
}
